import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-003.BzD9MPis.js";import{_ as o,o as _,c as l,a3 as e}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/15-刺权第九.md","filePath":"books/yan-tie-lun/15-刺权第九.md","lastUpdated":1784092560000}'),i={name:"books/yan-tie-lun/15-刺权第九.md"};function r(s,a,n,m,c,d){return _(),l("div",null,[...a[0]||(a[0]=[e('<p>刺权第九 【题解】</p><p>本篇的主旨是讥刺权贵。大夫炫耀“官尊者禄厚，本美者枝茂”，“夫贵于朝，妻贵于室”，嘲讽平民“居编户之列，而望卿相之子孙，是以跛夫之欲及楼季也，无钱而欲千金之宝，不亦虚望哉”。文学则指出，做官应该以天下为己任，而不是为了厚禄和妻子荣宠，“君子之仕，行其义，非乐其势也。受禄以润贤，非私其利”。两相对比，思想境界的高低是显而易见的。这说明地位高不等于认识水平高，官大不等于思想境界大。</p><p>大夫曰：“今夫越之具区[(1)]，楚之云梦[(2)]，宋之钜野[(3)]，齐之孟诸[(4)]，有国之富而霸王之资也。人君统而守之则强，不禁则亡。齐以其肠胃予人[(5)]，家强而不制[(6)]，枝大而折干，以专巨海之富而擅鱼盐之利也[(7)]。势足以使众，恩足以恤下[(8)]，是以齐国内倍而外附[(9)]。权移于臣，政坠于家，公室卑而田宗强[(10)]，转毂游海者盖三千乘[(11)]，失之于本而末不可救。今山川海泽之原，非独云梦、孟诸也。鼓铸煮盐[(12)]，其势必深居幽谷，而人民所罕至。奸猾交通山海之际[(13)]，恐生大奸[(14)]。乘利骄溢[(15)]，散朴滋伪[(16)]，则人之贵本者寡。大农盐铁丞咸阳、孔仅等上请[(17)]：‘愿募民自给费，因县官器，煮盐予用[(18)]，以杜浮伪之路[(19)]。’由此观之：令意所禁微[(20)]，有司之虑亦远矣。”</p><p>【注释】</p><p>[(1)]具区：湖泊名，即太湖。</p><p>[(2)]云梦：云梦泽。古云梦泽分为云泽、梦泽，江南为梦泽，江北为云泽。</p><p>[(3)]钜野：钜野泽，在今山东钜野北。</p><p>[(4)]孟诸：孟诸泽，在今河南商丘，今已淤没。</p><p>[(5)]以其肠胃予人：齐国将物产大权交给权臣管理。肠胃，比喻储藏丰富物产的地方。</p><p>[(6)]家：卿大夫采邑。</p><p>[(7)]巨海：大海。擅：垄断。</p><p>[(8)]恤下：笼络臣下。</p><p>[(9)]倍：通“背”，背叛君主。外附：归附权臣。</p><p>[(10)]公室：指国君。田宗：指田氏家族。田齐祖先出自陈氏。春秋时，陈国公子完因国乱奔齐，为田氏，子孙世为齐卿。公元前481年，陈完八世孙田常杀死齐简公而立平公，任相国，掌握了齐国大权。</p><p>[(11)]转毂（ɡǔ）：指车辆。毂，车轮中心有孔可以插轴的圆木。游海：来往于海边运输鱼盐。</p><p>[(12)]铸：原作“金”，据王利器说校改。</p><p>[(13)]奸猾：奸诈狡猾的人。交通：往来。之际：之间。</p><p>[(14)]大奸：指叛乱。</p><p>[(15)]乘利骄溢：凭借财利而骄傲自满。</p><p>[(16)]散朴：破坏朴实风气。散，原作“敦”，据孙贻让说校改。滋伪：滋长虚假作风。</p><p>[(17)]大农：大农令，汉武帝时掌管国家租税、盐铁、钱粮等财政收支的官吏。盐铁丞：大农属官，掌管盐铁官营。咸阳：东郭咸阳，齐地大盐商。孔仅：南阳大冶铁商。两人都家累千金。公元前120年，大司农郑当时推荐东郭咸阳、孔仅为盐铁丞。公元前119年，他们上书武帝募民自出资金，用官家器具煮盐，再由官家收购，实行专卖。</p><p>[(18)]予用：交付国家使用，即由国家收购。</p><p>[(19)]浮伪：虚浮造假。</p><p>[(20)]微：深微。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“现在越地的具区泽，楚地的云梦泽，宋地的钜野泽，齐地的孟诸泽，具有国家的财富，是霸王的资源。君主统一控制这些资源财富就强盛，不禁止他人占有就灭亡。当年齐就是将国家的肠胃——储藏物产大权——让给他人，导致卿大夫强盛而不可控制，枝叶过大，压断树干，让大夫垄断了大海的资源，独占了鱼盐的财利。大夫田氏势力大到足可以役使民众，恩惠足可以笼络臣下，所以齐国民众背叛君主而归附田氏。国家大权转移到大臣手中，政权坠入大夫采邑，君主微弱而田氏强盛，沿海运送鱼盐的车子多达三千辆。失去资源根本，其他末事就不可收拾了。如今山川海泽的资源，并不仅仅是云梦泽和孟诸泽。铸铁煮盐，其地势一定是在深山幽谷，为民众所罕至之处。奸诈狡猾之徒往来于深山大海之间，恐怕他们会生出大乱。他们凭借财利而骄傲自满，破坏了朴实风气，助长了虚假作风，这样重视农业根本的人就更少了。大农令属官盐铁丞东郭咸阳、孔仅等人上书请求：‘希望招募老百姓自己出钱，用官府提供的器具煮盐，再由国家收购，以杜绝虚浮作假的门路。’由此看来，盐铁禁令意义深微，主管官员的考虑非常深远啊。”</p><p>文学曰：“有司之虑远，而权家之利近[(1)]；令意所禁微，而僭奢之道著[(2)]。自利害之设[(3)]，三业之起[(4)]，贵人之家，云行于涂[(5)]，毂击于道[(6)]，攘公法[(7)]，申私利[(8)]，跨山泽[(9)]，擅官市，非特巨海鱼盐也[(10)]；执国家之柄，以行海内，非特田常之势、陪臣之权也[(11)]；威重于六卿，富累于陶、卫[(12)]，舆服僭于王公[(13)]，宫室溢于制度[(14)]，并兼列宅[(15)]，隔绝闾巷[(16)]，阁道错连[(17)]，足以游观，凿池曲道，足以骋骛，临渊钓鱼，放犬走兔，隆豺鼎力[(18)]，蹋鞠斗鸡[(19)]，中山素女抚流徵于堂上[(20)]，鸣鼓巴俞作于堂下[(21)]，妇女被罗纨[(22)]，婢妾曳</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>纻[(23)]，子孙连车列骑[(24)]，田猎出入，毕弋捷健[(25)]。是以耕者释耒而不勤[(26)]，百姓冰释而懈怠[(27)]。何者？己为之而彼取之，僭侈相效，上升而不息，此百姓所以滋伪而罕归本也[(28)]。”</p><p>【注释】</p><p>[(1)]权家：权豪之家。利近：私利靠近。</p><p>[(2)]僭奢：僭越奢侈。著：显著，明显。</p><p>[(3)]利害之设：设置兴利的官员。</p><p>[(4)]三业：盐铁、酒榷、均输。</p><p>[(5)]云行于涂：如同风起云涌般弥漫到道路之上。涂，同“途”。</p><p>[(6)]毂击于道：车轮轴在路上互相碰撞。</p><p>[(7)]攘公法：排斥国家的法令。</p><p>[(8)]申：通“伸”，伸张。</p><p>[(9)]跨：广占。</p><p>[(10)]非特：不仅。</p><p>[(11)]陪臣：古代诸侯对天子自称陪臣，大夫家臣对大夫自称陪臣。</p><p>[(12)]陶：陶朱公范蠡。卫：疑指子贡，《史记·仲尼弟子列传》载子贡“常相鲁卫，家累千金”。</p><p>[(13)]僭：僭越，超过。</p><p>[(14)]溢：意同“僭”，超过。</p><p>[(15)]并兼列宅：指收购成片的宅第。并兼，兼并，收购。列宅，成片的宅第。</p><p>[(16)]隔绝闾巷：富豪将成片宅第收归己有以后，原来的闾巷通道变成富豪住宅中的私人通道，不再对外开放。</p><p>[(17)]阁道错连：楼阁间架空的通道交错连接。</p><p>[(18)]隆豺：斗兽。鼎力：举鼎比较气力。</p><p>[(19)]蹋鞠（tà jū）：古代一种踢球的游戏。</p><p>[(20)]中山：战国时期诸侯国名，后为赵武灵王所灭，汉景帝又置中山诸侯国，在今河北中部偏西北一带。素女：能歌善舞的美女。抚流徵（zhǐ）：指弹琴。抚，通“拊”，拍。流，婉转。徵，古代五音之一。</p><p>[(21)]巴俞：巴渝舞。巴，在今四川巴县。俞，通“渝”，指渝水，即嘉陵江。作：起。</p><p>[(22)]罗纨：轻软的丝织品。</p><p>[(23)]</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>（chī）：细葛布。纻（zhù）：纻麻布。</p><p>[(24)]连车列骑：车马成行。</p><p>[(25)]毕弋：捕鸟用的网和箭，此处指捕鸟。毕，罗网。弋，带绳的箭。捷健：敏捷矫健。</p><p>[(26)]耒（lěi）：一种农具。</p><p>[(27)]冰释：冰融化，此处指涣散。</p><p>[(28)]滋伪：滋长作伪。罕：少。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“主管官员考虑深远，而权豪家族私利却靠近了；盐铁禁令意义深微，而僭越奢侈的风气却更加明显了。自从朝廷设置兴利的官员，盐铁、酒榷、均输三项官营事业兴起，富贵人家，如同风起云涌般弥漫到道路之上，车轮轴在路上互相撞击。他们攘弃国家法令，伸张私人利益，广泛占有山林川泽，垄断官方集市，不仅仅是大海的鱼盐而已；他们执掌国家权柄，肆行海内，不仅仅拥有田常、陪臣的权势而已；他们的权威比晋国六卿还重，他们的财富比陶朱公范蠡、卫国子贡还多，车马服饰超过王公大人，宫室建筑超越了制度规定。他们收购成片的宅第，隔绝闾巷的公共通道，楼阁间架空的通道交错连接，足可以游览观赏；在宅第之内开凿水池，修建曲折的通道，足可以驰骋追逐；在深池钓鱼，放纵狗兔赛跑，驯兽取乐，举鼎较力，踢球斗鸡；中山美女在堂上弹奏曼妙的歌曲，巴俞舞女在堂下伴随鼓点跳起舞蹈；妇女穿着轻软的丝绸衣服，婢妾拖曳着细葛麻布的长裙；子孙们车马成行，往来打猎，捕捉鸟兽，身姿敏捷矫健。所以耕田的人放下锄头而不再勤苦，老百姓人心涣散而松懈怠惰。为什么呢？自己这样做了，别人也就跟着模仿，僭越奢侈，相互仿效，风气甚嚣尘上，不能停息，这就是老百姓滋长作伪而很少归于农业根本的原因。”</p><p>大夫曰：“官尊者禄厚，本美者枝茂。故文王德而子孙封，周公相而伯禽富[(1)]。水广者鱼大，父尊者子贵。《传》曰：‘河、海润千里。’[(2)]盛德及四海，况之妻子乎[(3)]？故夫贵于朝，妻贵于室，富曰苟美[(4)]，古之道也。《孟子》曰：‘王者与人同，而如彼者，居使然也。’[(5)]居编户之列[(6)]，而望卿相之子孙，是以跛夫之欲及楼季也[(7)]，无钱而欲千金之宝，不亦虚望哉？”</p><p>【注释】</p><p>[(1)]周公相而伯禽富：伯禽是周公之子，周公因为要留在中央王朝辅佐成王，因此委派伯禽代替自己就封于鲁。</p><p>[(2)]河、海润千里：见于《春秋公羊传·僖公三十一年》。河，黄河。海，大海。润，滋润。</p><p>[(3)]之：其。</p><p>[(4)]富曰苟美：见于《论语·子路》：“子谓卫公子荆，善居室，始有，曰：‘苟合矣！’少有，曰：‘苟完矣！’富有，曰：“苟美矣！’”富曰苟美，意为家里富有，差不多美好了。</p><p>[(5)]王者与人同，而如彼者，居使然也：见于《孟子·尽心上》。彼，指那样阔气。居，所处的地位。</p><p>[(6)]编户：指列于国家户口簿的平民。</p><p>[(7)]楼季：战国时期魏文侯之弟，善于行走攀登。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“官大的人俸禄优厚，根深的树枝叶茂盛。因此周文王有德而子孙接受封赏，周公为相而伯禽富贵。湖水深广，鱼就肥大；父亲位尊，儿子就高贵。《春秋公羊传·僖公三十一年》说：‘黄河、大海滋润千里。’盛大的恩德普及四海，何况他的妻子儿女呢？因此丈夫在朝廷显贵，妻子就在家里尊贵，富有是美好的事，这是自古以来的道理。《孟子·尽心上》说：‘君王与常人相同，而他那样阔气，是地位使他如此。’处于平民之列，而指望自己的子孙出将入相，这是希望跛脚的人赶上善跑的楼季，无钱而想得到千金珍宝，这不是痴心妄想吗？”</p><p>文学曰：“禹、稷自布衣[(1)]，思天下有不得其所者，若己推而纳之沟中，故起而佐尧，平治水土[(2)]，教民稼穑[(3)]。其自任天下如此其重也[(4)]，岂云食禄以养妻子而已乎？夫食万人之力者[(5)]，蒙其忧[(6)]，任其劳[(7)]。一人失职，一官不治，皆公卿之累也[(8)]。故君子之仕，行其义，非乐其势也。受禄以润贤[(9)]，非私其利。见贤不隐[(10)]，食禄不专[(11)]，此公叔之所以为文[(12)]，魏成子所以为贤也[(13)]。故文王德成而后封子孙[(14)]，天下不以为党[(15)]，周公功成而后受封，天下不以为贪。今则不然。亲戚相推，朋党相举，父尊于位，子溢于内，夫贵于朝，妻谒行于外[(16)]。无周公之德而有其富，无管仲之功而有其侈，故编户跛夫而望疾步也。”</p><p>【注释】</p><p>[(1)]稷：后稷，周人始祖，名弃，被尧封于邰，故地在今陕西武功。《尚书·尧典》载帝舜命弃担任后稷之官，负责教民耕种。后，君。稷，农官。</p><p>[(2)]平治水土：指大禹治水。</p><p>[(3)]教民稼穑：指后稷教民耕种。</p><p>[(4)]自任天下：以天下为己任。</p><p>[(5)]食万人之力：指食用万人劳动所得的俸禄。</p><p>[(6)]蒙其忧：蒙受老百姓的忧患。</p><p>[(7)]任其劳：分担老百姓的劳苦。</p><p>[(8)]累：过失。</p><p>[(9)]润贤：培养贤才。</p><p>[(10)]见贤不隐：看到贤人不隐瞒，即举贤。</p><p>[(11)]专：独享。</p><p>[(12)]公叔：复姓，此处指卫国大夫公叔枝，谥号为“文”，故称公叔文子。公叔文子的家臣僎是个贤才，由于公叔文子的推荐，做了卫国大夫，孔子知道后说：“公叔枝可以谥为文了。”事见《论语·宪问》。</p><p>[(13)]魏成子：战国初期魏国人，为魏文侯丞相。他用十分之九的俸禄去招聘贤士。</p><p>[(14)]故文王德成而后封子孙：此句原作“故周德成而后封子孙”，据王利器说校改。</p><p>[(15)]天下不以为党：此句原无“天下”二字，据卢文弨说校补。党，指亲属或家族。</p><p>[(16)]妻谒（yè）：妻子弄权接受请托。谒，请托。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“大禹、后稷起于布衣平民，他们想到天下有不得其所的人，就好像自己把他们推到沟中，因此出来辅佐帝尧，大禹平治水土，后稷教民稼穑。他们以天下为己任，对此那样看重，怎么能说食用俸禄仅仅是为了养活妻子儿女呢？食用万人劳动所得的俸禄的人，应该蒙受老百姓的忧患，分担老百姓的劳苦。一个人失职，一个官员不称职，都可以看作是公卿的过失。因此君子当官，是为了实行仁义，不是享受当官的权势。接受俸禄可以用来养贤，而不是谋取私利。看到贤才不应该隐瞒，食用俸禄不是独享，这就是公叔枝谥号为“文”，魏成子被称为贤人的原因。因此周文王施行仁德而后子孙封赏，天下人并不认为他偏袒亲属；周公大功告成而后接受封赏，天下并不以为他贪婪。现在的情况不是这样。父母亲戚之间互相推荐，朋党之间互相推举，父亲高官尊位，儿子在家骄傲自满；丈夫在朝廷显贵，妻子在外接受请托。没有周公的美德却有周公的富贵，没有管仲的功劳却有管仲的奢侈，因而平民奢望得到卿相富贵，跛脚之人希望疾步如飞。”</p>',97)])])}const z=o(i,[["render",r]]);export{u as __pageData,z as default};
